const CHUNK = 500;

function chunked<T>(items: readonly T[]): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += CHUNK) out.push(items.slice(i, i + CHUNK));
  return out;
}

export interface PurgeResult {
  readonly issuesPurged: number;
  readonly storageMbFreed: number;
}

/**
 * Permanently deletes every issue of the org archived at or before `cutoff`,
 * with its labels links, comments, attachments and search documents. Each
 * project's number high-water mark is raised first so numbers are never reused.
 */
export async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<PurgeResult> {
  const db = getDb();
  return db.transaction((tx) => {
    const expired = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
        ),
      )
      .all();
    if (expired.length === 0) return { issuesPurged: 0, storageMbFreed: 0 };

    const maxByProject = new Map<string, number>();
    for (const row of expired) {
      maxByProject.set(
        row.projectId,
        Math.max(maxByProject.get(row.projectId) ?? 0, row.number),
      );
    }
    for (const [projectId, max] of maxByProject) {
      tx.update(projects)
        .set({
          issueNumberHighWater: sql`max(${projects.issueNumberHighWater}, ${max})`,
        })
        .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
        .run();
    }

    let storageMbFreed = 0;
    for (const ids of chunked(expired.map((row) => row.id))) {
      const commentIds = tx
        .select({ id: comments.id })
        .from(comments)
        .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)))
        .all()
        .map((row) => row.id);

      const sizes = tx
        .select({ sizeBytes: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(orgPredicate(attachments.orgId, orgId), inArray(attachments.issueId, ids)),
        )
        .all();
      for (const size of sizes) {
        storageMbFreed += Math.ceil(size.sizeBytes / (1024 * 1024));
      }

      for (const part of chunked(commentIds)) {
        tx.delete(searchIndex)
          .where(
            and(
              orgPredicate(searchIndex.orgId, orgId),
              eq(searchIndex.subjectKind, "comment"),
              inArray(searchIndex.subjectId, part),
            ),
          )
          .run();
      }
      tx.delete(searchIndex)
        .where(
          and(
            orgPredicate(searchIndex.orgId, orgId),
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, ids),
          ),
        )
        .run();
      tx.delete(comments)
        .where(and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)))
        .run();
      tx.delete(attachments)
        .where(
          and(orgPredicate(attachments.orgId, orgId), inArray(attachments.issueId, ids)),
        )
        .run();
      tx.delete(issueLabels)
        .where(
          and(orgPredicate(issueLabels.orgId, orgId), inArray(issueLabels.issueId, ids)),
        )
        .run();
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
        .run();
    }

    return { issuesPurged: expired.length, storageMbFreed };
  });
}
